/*
 * Share-card images (Open Graph / Twitter). Static JPEGs in public/og, generated by
 * scripts/generate-og-images.ts from the landing copy, fonts and artwork. They are plain
 * public files: no session, no middleware, reachable by any link-preview crawler.
 * Rename the files whenever the artwork changes, because platforms cache by URL.
 */
import { landingCopy, type LandingLang } from "@/features/landing/content";
import { SITE_NAME } from "@/lib/site";

export const SOCIAL_IMAGE = { width: 1200, height: 630, type: "image/jpeg" } as const;

export const SOCIAL_IMAGE_PATHS: Record<LandingLang, string> = {
  zh: "/og/ai-generator-zh.jpg",
  en: "/og/ai-generator-en.jpg",
};

/** The words drawn on the card, so the alt text always matches the image. */
export function socialImageText(lang: LandingLang) {
  const copy = landingCopy[lang];
  return { headline: copy.hero.lines, tagline: copy.hero.foot[0] };
}

export function socialImageAlt(lang: LandingLang): string {
  const { headline, tagline } = socialImageText(lang);
  return lang === "zh"
    ? `${SITE_NAME}：${headline.join("")}${tagline}。`
    : `${SITE_NAME}: ${headline.join(" ")} ${tagline}.`;
}

export function socialImage(lang: LandingLang) {
  return { url: SOCIAL_IMAGE_PATHS[lang], alt: socialImageAlt(lang), ...SOCIAL_IMAGE };
}
